/// <summary>
/// CB167_PerformStockReservation
/// This is a controller class for reserve event orders batch job.
/// </summary>
class METReserveEventOrdersController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Sets service and its method.
/// </summary>
protected void new()
{
    super(classstr(METReserveEventOrdersService), methodstr(METReserveEventOrdersService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Sets caption for the batch job.
/// </summary>
/// <returns>Caption.</returns>
protected ClassDescription defaultCaption()
{
    return "@MET:METReserveEventOrders";
}

/// <summary>
/// Starts the batch job processing.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METReserveEventOrdersController controller = new METReserveEventOrdersController();

    controller.parmArgs(_args);

    controller.startOperation();
}
